}

{
    if (!len) return 0;
    while (--len && *str1 && *str1 == *str2) { str1++; str2++; }

#if defined(_WIN64) || defined(_UCRT) || _MSVCR_VER == 70 || _MSVCR_VER == 71 || _MSVCR_VER >= 110
    if ((unsigned char)*str1 > (unsigned char)*str2) return 1;
